package cn.academy.port.skill;
import java.io.File;import java.net.*;import java.nio.file.Path;import java.util.*;
/** Actual class signature linkage with client namespaces forbidden. No native game bootstrap claimed. */
public final class TeleporterProgressionServerLinkTest {
 private static final class ServerLoader extends URLClassLoader{int requests;ServerLoader(URL[] urls){super(urls,ClassLoader.getPlatformClassLoader());}@Override protected Class<?> loadClass(String name,boolean resolve)throws ClassNotFoundException{if(name.startsWith("net.minecraft.client.")||name.startsWith("net.neoforged.neoforge.client.")||name.startsWith("cn.academy.port.client.")){requests++;throw new ClassNotFoundException("server denies "+name);}return super.loadClass(name,resolve);}}
 public static void main(String[] args)throws Exception{var urls=new ArrayList<URL>();for(String p:System.getProperty("java.class.path").split(java.util.regex.Pattern.quote(File.pathSeparator)))urls.add(Path.of(p).toUri().toURL());int count=0;try(var loader=new ServerLoader(urls.toArray(URL[]::new))){for(String name:List.of("TeleporterProgressionRules","TeleporterProgressionSupport","PenetrateTeleport","MarkTeleport","FleshRipping")){var queue=new ArrayDeque<Class<?>>();queue.add(Class.forName("cn.academy.port.skill."+name,false,loader));while(!queue.isEmpty()){var c=queue.remove();c.getDeclaredConstructors();c.getDeclaredMethods();c.getDeclaredFields();queue.addAll(List.of(c.getDeclaredClasses()));count++;}}var trig=Class.forName("cn.academy.port.clientless.ClassicLateTrig",false,loader);trig.getDeclaredMethods();count++;if(loader.requests!=0)throw new AssertionError("Common Teleporter gameplay linked client");}System.out.println("PASS "+count+" common Teleporter classes coldlinked with client namespaces denied");}
}
